#include <iostream>
#include <utility>
#include <vector>
using namespace std;

int main() {
    vector<int> a = {1, 2, 3};
    vector<int> b = move(a);
    cout << b.size() << endl;
    cout << a.empty() << endl;
    return 0;
}

#include <cstddef>
#include <iostream>
#include <utility>
using namespace std;

class Buffer {
public:
    explicit Buffer(size_t n) : data_(new int[n]), size_(n) {
        cout << "made" << endl;
    }
    Buffer(Buffer&& other) noexcept : data_(other.data_), size_(other.size_) {
        other.data_ = nullptr;
        other.size_ = 0;
        cout << "moved" << endl;
    }
    Buffer(const Buffer&) = delete;
    ~Buffer() { delete[] data_; }
    size_t size() const { return size_; }

private:
    int* data_;
    size_t size_;
};

int main() {
    Buffer a(100);
    Buffer b = move(a);
    cout << b.size() << " " << a.size() << endl;
    return 0;
}

